function checkLayer(callFrom, callTo) {
  const order = { controller: 0, service: 1, repository: 2 };
  if (order[callTo] >= order[callFrom]) {
    return "OK: 依赖指向更底层";
  }
  return "BAD: " + callFrom + " 不应依赖 " + callTo + "（破坏分层）";
}
